<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { call } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { notifyError } from '../composables/toast'
import { clampPct, fmtNum, fmtNumFixed } from '../composables/realisasiFormat'
import { useListPersistence } from '../composables/useListPersistence'

const listPersistence = useListPersistence('FidFpdDashboard')

// Pembungkus portal, bukan API desk langsung: isinya tetap dari desk apa adanya,
// tapi penolakannya dijaga server sehingga URL halaman ini tidak bisa dibuka
// oleh yang tidak berhak.
const API = 'juragan.api.portal.fid_fpd_dashboard'

// Jingga kemerahan — FID/FPD adalah metrik risiko, dan warnanya membedakan
// dashboard ini dari tiga kartu lain di Home.
const FF_GRADIENT = 'linear-gradient(135deg, #3a1c1c 0%, #7a2e22 55%, #d4572a 100%)'

const BULAN = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
const GRACE = [0, 7, 15, 30]
const KATEGORI = [
	{ value: 'all', short: 'All' },
	{ value: 'mokas', short: 'Mokas' },
	{ value: 'enduser', short: 'End User' },
]
const TABS = [
	{ value: 'berjalan', label: 'Bulan Berjalan' },
	{ value: 'cutoff', label: 'Cut Off Bulan Sebelumnya' },
]
const MARKETING_PREVIEW = 5
const RING = 2 * Math.PI * 52

const now = new Date()
const loading = ref(false)
const loadingMarketing = ref(false)
const loadingNasabah = ref(false)
const fatalError = ref('')
const showFilter = ref(false)
const kategori = ref('all')
const heatmapMode = ref('fid')
const heatmapDisplay = ref('pct')
// Grace berlaku PER BAGIAN, bukan global — KPI, tren, dan kategori di desk
// selalu memakai grace 0, hanya heatmap & daftar marketing yang memakainya.
const heatmapGrace = ref(0)
const listGrace = ref(0)
const tab = ref('berjalan')
const cariMarketing = ref('')
const marketingExpanded = ref(false)
const nasabahSheet = ref(null)
const nasabahMetric = ref('fid')

const filters = reactive({
	cabang: 'ALL',
	bulan: now.getMonth() + 1,
	tahun: now.getFullYear(),
})
const draft = reactive({ ...filters })

const opsi = ref(null)
const kpi = ref(null)
const line = ref(null)
const breakdown = ref(null)
const heatmap = ref(null)
const marketing = ref([])
const nasabah = ref([])

const cabangOptions = computed(() => opsi.value?.cabang_options || [])
const yearOptions = computed(() => {
	const min = Number(opsi.value?.min_year) || now.getFullYear()
	const max = Math.max(Number(opsi.value?.current_year) || now.getFullYear(), filters.tahun)
	const years = []
	for (let y = max; y >= min; y--) years.push(y)
	return years
})

const periodeLabel = computed(() => `${BULAN[filters.bulan - 1]} ${filters.tahun}`)
const cabangLabel = computed(() => {
	if (opsi.value?.locked_cabang) return opsi.value.locked_cabang
	if (filters.cabang && filters.cabang !== 'ALL') return filters.cabang
	return 'Konsolidasi'
})
const scopeLabel = computed(() => {
	if (!opsi.value) return 'Rasio keterlambatan bayar'
	if (opsi.value.locked_cabang) return `Cabang ${opsi.value.locked_cabang}`
	return 'Konsolidasi seluruh cabang'
})

const activeFilterCount = computed(() => {
	let n = 0
	if (filters.cabang && filters.cabang !== 'ALL') n++
	if (filters.bulan !== now.getMonth() + 1 || filters.tahun !== now.getFullYear()) n++
	return n
})

// FID & FPD sama pentingnya, jadi keduanya berdampingan di kartu utama.
const metrikUtama = computed(() => {
	const k = kpi.value || {}
	return [
		{
			key: 'FID',
			color: '#fb923c',
			pct: k.fid_pct?.current,
			delta: k.fid_pct?.delta,
			unit: k.fid_unit?.current,
			denominator: k.fid_pct?.denominator,
		},
		{
			key: 'FPD',
			color: '#f87171',
			pct: k.fpd_pct?.current,
			delta: k.fpd_pct?.delta,
			unit: k.fpd_unit?.current,
			denominator: k.fpd_pct?.denominator,
		},
	]
})

const rincian = computed(() => {
	const k = kpi.value || {}
	return [
		{
			key: 'FID',
			color: '#f97316',
			items: [
				{ label: 'Populasi', value: k.fid_target_all },
				{ label: 'Selesai', value: k.fid_done },
				{ label: 'Partial', value: k.fid_partial },
				{ label: 'Tarikan', value: k.fid_tarikan },
			],
		},
		{
			key: 'FPD',
			color: '#dc2626',
			items: [
				{ label: 'Populasi', value: k.fpd_target_all },
				{ label: 'Selesai', value: k.fpd_done },
				{ label: 'Tarikan', value: k.fpd_tarikan },
			],
		},
	]
})

const trenBulan = computed(() => {
	const d = line.value
	if (!d) return []
	return (d.labels || []).map((label, i) => ({
		label: label.slice(0, 3),
		fid: Number(d.fid_pct?.[kategori.value]?.[i]) || 0,
		fpd: Number(d.fpd_pct?.[kategori.value]?.[i]) || 0,
	}))
})
// Skala sumbu Y dibulatkan ke atas ke kelipatan 5 supaya garis bantunya rapi.
const maxTren = computed(() => {
	const tertinggi = Math.max(1, ...trenBulan.value.flatMap((m) => [m.fid, m.fpd]))
	return Math.ceil(tertinggi / 5) * 5 || 5
})

const TREN_W = 300
const TREN_H = 120

function trenX(i) {
	const n = Math.max(1, trenBulan.value.length - 1)
	return (i / n) * TREN_W
}

function trenY(v) {
	return TREN_H - (Math.max(0, Number(v) || 0) / maxTren.value) * TREN_H
}

const trenSeries = computed(() =>
	[
		{ key: 'fid', color: '#f97316' },
		{ key: 'fpd', color: '#dc2626' },
	].map((ser) => ({
		...ser,
		points: trenBulan.value
			.map((m, i) => `${trenX(i).toFixed(2)},${trenY(m[ser.key]).toFixed(2)}`)
			.join(' '),
	})),
)

const trenTitik = computed(() =>
	trenSeries.value.flatMap((ser) =>
		trenBulan.value.map((m, i) => ({
			key: `${ser.key}-${i}`,
			color: ser.color,
			x: trenX(i),
			y: trenY(m[ser.key]),
		})),
	),
)

const trenGrid = computed(() => {
	const langkah = maxTren.value / 4
	return [0, 1, 2, 3, 4].map((i) => {
		const v = maxTren.value - langkah * i
		return { v, y: trenY(v) }
	})
})

const marketingTersaring = computed(() => {
	const q = cariMarketing.value.trim().toLowerCase()
	if (!q) return marketing.value
	return marketing.value.filter((r) => (r.marketing || '').toLowerCase().includes(q))
})
const marketingTampil = computed(() =>
	marketingExpanded.value
		? marketingTersaring.value
		: marketingTersaring.value.slice(0, MARKETING_PREVIEW),
)

// ---- Format & warna --------------------------------------------------------
function int(value) {
	if (value === null || value === undefined) return '—'
	return fmtNum(value, 0)
}

function pct(value) {
	if (value === null || value === undefined) return 'n/a'
	return `${fmtNumFixed(value, 2)}%`
}

/** Selisih persentase; FID/FPD naik itu buruk, jadi tandanya tetap apa adanya. */
function deltaPoin(value) {
	if (value === null || value === undefined) return 'n/a'
	const n = Number(value)
	if (!Number.isFinite(n)) return 'n/a'
	return `${n > 0 ? '+' : ''}${fmtNumFixed(n, 2)} poin`
}

function barHeight(value, max) {
	const v = Math.max(0, Number(value) || 0)
	return `${Math.min(100, (v / max) * 100)}%`
}

// Ambang rasio risiko: makin kecil makin baik.
function rasioClass(value) {
	const p = Number(value)
	if (!Number.isFinite(p)) return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
	if (p <= 5) return 'bg-ui-surface-green-50 text-ui-ink-green-600'
	if (p <= 15) return 'bg-ui-surface-amber-50 text-ui-ink-amber-600'
	return 'bg-ui-surface-red-50 text-ui-ink-red-600'
}

/**
 * Berapa bagian yang akhirnya selesai dalam toleransi, per metrik.
 * Persentasenya diturunkan dari dua kolom yang sama dengan yang ditampilkan
 * (selesai dibagi unit), jadi angkanya bisa ditelusuri langsung dari barisnya.
 */
function selesaiChips(row) {
	return ['FID', 'FPD'].map((key) => {
		const bawah = key.toLowerCase()
		const total = Number(row[`${bawah}_unit`]) || 0
		const selesai = Number(row[`${bawah}_selesai`]) || 0
		return {
			key,
			total,
			selesai,
			pct: total ? (selesai / total) * 100 : null,
		}
	})
}

function rankClass(rank) {
	if (rank === 1) return 'bg-ui-surface-red-100 text-ui-ink-red-700'
	if (rank === 2) return 'bg-ui-surface-orange-100 text-ui-ink-orange-700'
	if (rank === 3) return 'bg-ui-surface-amber-100 text-ui-ink-amber-700'
	return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
}

/** Isi sel mengikuti pilihan tampilan; mode persen diberi simbolnya. */
function selTeks(sel) {
	if (!sel || !sel.denominator) return ''
	if (heatmapDisplay.value === 'unit') return fmtNum(sel.unit, 0)
	return `${fmtNum(sel.pct, 1)}%`
}

/** Sel heatmap: pekat mengikuti besarnya rasio, kosong bila tanpa populasi. */
function selStyle(sel) {
	if (!sel || !sel.denominator) return { background: '#f1f5f9', color: '#cbd5e1' }
	const p = Math.min(100, Math.max(0, Number(sel.pct) || 0))
	const alpha = 0.12 + Math.min(1, p / 40) * 0.78
	// Keep the chart's original red-on-white scale, including in dark themes.
	const tint = `rgba(220,38,38,${alpha.toFixed(2)})`
	return {
		background: `linear-gradient(${tint}, ${tint}), #fff`,
		color: alpha > 0.55 ? '#fff' : '#7f1d1d',
	}
}

// ---- Aksi ------------------------------------------------------------------
function openFilter() {
	Object.assign(draft, filters)
	showFilter.value = true
}

function resetFilter() {
	draft.cabang = 'ALL'
	draft.bulan = now.getMonth() + 1
	draft.tahun = now.getFullYear()
}

function applyFilter() {
	Object.assign(filters, draft)
	if (
		filters.cabang === 'ALL' &&
		filters.bulan === now.getMonth() + 1 &&
		filters.tahun === now.getFullYear()
	) {
		listPersistence.clearSession()
	} else {
		listPersistence.writeSession({ filters })
	}
	showFilter.value = false
	loadAll()
}

// KPI, tren, dan kategori memakai grace 0 — sama dengan desk. Grace hanya
// dipakai heatmap & daftar marketing lewat kontrolnya masing-masing.
function args(grace = 0) {
	return {
		cabang: filters.cabang,
		bulan: filters.bulan,
		tahun: filters.tahun,
		grace_period: grace,
	}
}

function setKategori(value) {
	// Kategori hanya mengubah deret yang ditampilkan; datanya sudah lengkap.
	kategori.value = value
}

async function setHeatmap({ mode, grace }) {
	if (mode !== undefined) {
		if (heatmapMode.value === mode) return
		heatmapMode.value = mode
	}
	if (grace !== undefined) {
		if (heatmapGrace.value === grace) return
		heatmapGrace.value = grace
	}
	await loadHeatmap()
}

async function setTab(value) {
	if (tab.value === value) return
	tab.value = value
	await loadMarketing()
}

async function setListGrace(g) {
	if (listGrace.value === g) return
	listGrace.value = g
	await loadMarketing()
}

async function loadHeatmap() {
	try {
		heatmap.value = await call(`${API}.get_heatmap`, {
			tahun: filters.tahun,
			cabang: filters.cabang,
			mode: heatmapMode.value,
			kategori: 'all',
			grace_period: heatmapGrace.value,
		})
	} catch (e) {
		heatmap.value = null
		notifyError(e, 'Gagal memuat heatmap')
	}
}

async function loadMarketing() {
	loadingMarketing.value = true
	marketingExpanded.value = false
	try {
		marketing.value =
			(await call(`${API}.get_list_marketing`, {
				...args(listGrace.value),
				tab: tab.value,
			})) || []
	} catch (e) {
		marketing.value = []
		notifyError(e, 'Gagal memuat performa marketing')
	} finally {
		loadingMarketing.value = false
	}
}

async function bukaNasabah(row) {
	nasabahSheet.value = row
	nasabahMetric.value = 'fid'
	await loadNasabah()
}

async function setNasabahMetric(metric) {
	if (nasabahMetric.value === metric) return
	nasabahMetric.value = metric
	await loadNasabah()
}

async function loadNasabah() {
	const row = nasabahSheet.value
	if (!row) return
	loadingNasabah.value = true
	try {
		nasabah.value =
			(await call(`${API}.get_nasabah_detail`, {
				...args(listGrace.value),
				nama_marketing: row.marketing,
				tab: tab.value,
				metric: nasabahMetric.value,
			})) || []
	} catch (e) {
		nasabah.value = []
		notifyError(e, 'Gagal memuat daftar nasabah')
	} finally {
		loadingNasabah.value = false
	}
}

async function loadAll() {
	loading.value = true
	try {
		if (!opsi.value) {
			opsi.value = await call(`${API}.get_filter_options`)
			// Pimpinan Cabang terkunci ke cabangnya; filter cabang tidak berlaku.
			if (opsi.value?.locked_cabang) filters.cabang = opsi.value.locked_cabang
		}
		const [k, l, b] = await Promise.all([
			call(`${API}.get_kpi`, args()),
			call(`${API}.get_line_chart`, {
				tahun: filters.tahun,
				cabang: filters.cabang,
				grace_period: 0,
			}),
			call(`${API}.get_breakdown`, args()),
		])
		kpi.value = k
		line.value = l
		breakdown.value = b
		fatalError.value = ''
		loadHeatmap()
		await loadMarketing()
	} catch (e) {
		if (!kpi.value) fatalError.value = errorText(e)
		else notifyError(e, 'Gagal memuat Dashboard FID / FPD')
	} finally {
		loading.value = false
	}
}

async function reload() {
	if (loading.value) return
	await loadAll()
}

// Pesan Frappe datang sebagai `messages` (list HTML) atau `message`.
function errorText(e) {
	const raw = e?.messages?.join(' ') || e?.message || ''
	const text = String(raw)
		.replace(/<[^>]*>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
	return text || 'Anda tidak punya akses ke dashboard ini.'
}

onMounted(async () => {
	await refreshCsrfToken()
	try {
		opsi.value = await call(`${API}.get_filter_options`)
	} catch {}
	const saved = listPersistence.readSession({
		filters: { cabang: 'ALL', bulan: now.getMonth() + 1, tahun: now.getFullYear() },
	}).filters
	const allowedBranches = [
		'ALL',
		...cabangOptions.value.map((option) =>
			typeof option === 'string' ? option : option.value,
		),
	]
	filters.cabang =
		opsi.value?.locked_cabang ||
		(allowedBranches.includes(saved.cabang) ? saved.cabang : 'ALL')
	if (saved.bulan >= 1 && saved.bulan <= 12) filters.bulan = saved.bulan
	if (yearOptions.value.includes(saved.tahun)) filters.tahun = saved.tahun
	await loadAll()
})
</script>
